// Given: visual algorithm for V1 (pill 1.4). Do not edit this file.
//
// A unit-mass spring, x'' = -w^2 x, stepped with explicit and with
// semi-implicit Euler. Deliberately standalone (OQ-11): your integrate()
// only handles gravity, so the visual runs its own two-line steps.
//
// Energy E = (v^2 + w^2 x^2) / 2. Pill 1.4 derives why explicit Euler
// multiplies E by exactly (1 + w^2 dt^2) every step, while semi-implicit
// Euler keeps E within about w*dt/2 of a constant.

export type EnergySeries = { t: number[]; explicit: number[]; semiImplicit: number[] };

export function springEnergies(dt: number, seconds: number, omega = 2 * Math.PI): EnergySeries {
  const w2 = omega * omega;
  const energy = (x: number, v: number) => 0.5 * (v * v + w2 * x * x);
  let xe = 1;
  let ve = 0;
  let xs = 1;
  let vs = 0;
  const out: EnergySeries = { t: [0], explicit: [energy(xe, ve)], semiImplicit: [energy(xs, vs)] };
  const steps = Math.round(seconds / dt);
  for (let i = 1; i <= steps; i++) {
    // Explicit: both updates use the old values.
    const xe1 = xe + ve * dt;
    const ve1 = ve - w2 * xe * dt;
    xe = xe1;
    ve = ve1;
    // Semi-implicit: velocity first, then position with the new velocity.
    vs = vs - w2 * xs * dt;
    xs = xs + vs * dt;
    out.t.push(i * dt);
    out.explicit.push(energy(xe, ve));
    out.semiImplicit.push(energy(xs, vs));
  }
  return out;
}
